#!/usr/bin/env python
"""Bounded asset-complete DATA-02 financial availability runner."""

from __future__ import annotations

import argparse
import hashlib
import json
import os
import sys
from datetime import UTC, date, datetime
from pathlib import Path
from typing import Any

os.environ.setdefault("DJANGO_SETTINGS_MODULE", "core.settings")
import django

django.setup()

from django.conf import settings
from django.db import connection, transaction
from django.db.models import Count, Q
from django.utils import timezone

from apps.data_center.application.current_fact_remediation import (
    FinancialAvailabilityBackfillUseCase,
)
from apps.data_center.application.query_services import list_active_stock_codes_for_backfill
from apps.data_center.infrastructure.financial_fact_repository import FinancialFactRepository
from apps.data_center.infrastructure.models import FinancialFactModel

SOURCE = "akshare"
MAX_BATCHES = 10
MAX_ASSETS = 20
MAX_ROWS = 2_000
LOCAL_BACKUP_SHA256 = "e806581fd317401f7af25f75d0d9801f8cb09de6558a3e7e9708f84dca60c54c"
REMOTE_BACKUP_SHA256 = "2dcfc4d76352516a24cbfc79226a459ae33fd727081339537c15d6e9f67b9d9b"
EXPECTED_COMMIT = "0e9f890e8185d897630fd937b5ffc220fd7830ce"
EXPECTED_RELEASE = "20260907170119"
EXPECTED_IMAGE = "sha256:778e50018124dd4d67dbe6a607b495d2e480c1bc6ff1aed42a9f50f484331e1e"
EXPECTED_UNIVERSE_HASH = "1579f1d52f3a58129102bfb090ed25ca2af0e56e6fe880722f7b6ae1e66c5a69"


class StopRun(RuntimeError):
    """A fail-closed guard failure."""

    def __init__(self, code: str, message: str) -> None:
        super().__init__(message)
        self.code = code
        self.message = message


class UncertainCommit(StopRun):
    """The write body completed but its commit result is uncertain."""

    def __init__(self, message: str) -> None:
        super().__init__("uncertain_commit", message)


def norm(value: Any) -> Any:
    """Normalize ORM values for evidence and exact comparisons."""

    return json.loads(json.dumps(value, default=str, sort_keys=True))


def digest(value: Any) -> str:
    """Return a stable SHA-256 JSON digest."""

    return hashlib.sha256(
        json.dumps(value, default=str, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode()
    ).hexdigest()


def universe_hash(universe: list[str]) -> str:
    """Use the canonical universe hash used by the existing evidence."""

    return hashlib.sha256(json.dumps(universe, separators=(",", ":")).encode()).hexdigest()


def candidate_identity() -> dict[str, str]:
    """Verify and return the release identity bound to this run."""

    try:
        manifest = json.loads(Path(settings.AGOM_RELEASE_MANIFEST_PATH).read_text())
    except Exception as exc:
        raise StopRun("candidate_drift", "Release manifest could not be read") from exc
    identity = {
        "source_commit": manifest.get("source_commit", ""),
        "release_tag": manifest.get("release_tag", ""),
        "image_id": manifest.get("image_id", ""),
    }
    expected = {
        "source_commit": EXPECTED_COMMIT,
        "release_tag": EXPECTED_RELEASE,
        "image_id": EXPECTED_IMAGE,
    }
    if identity != expected:
        raise StopRun("candidate_drift", f"Release identity {identity!r} != expected")
    return identity


def configure(read_only: bool) -> None:
    """Configure one transaction and fail closed on connection drift."""

    mode = "READ ONLY" if read_only else "READ WRITE"
    with connection.cursor() as cursor:
        cursor.execute(f"SET TRANSACTION ISOLATION LEVEL REPEATABLE READ, {mode}")
        cursor.execute("SET LOCAL lock_timeout = '3s'")
        cursor.execute("SET LOCAL statement_timeout = '30s'")
        cursor.execute("SELECT current_setting('TimeZone'), current_setting('transaction_read_only')")
        tz, ro = cursor.fetchone()
    expected = "on" if read_only else "off"
    if tz != "UTC" or ro != expected:
        raise StopRun("transaction_guard", f"timezone={tz!r}, read_only={ro!r}")


def load_universe() -> list[str]:
    """Load the formal active backfill universe."""

    raw = list(list_active_stock_codes_for_backfill())
    if not raw or not all(isinstance(code, str) and code for code in raw):
        raise StopRun("universe", "Formal universe is empty or invalid")
    result = sorted(set(raw))
    if not result:
        raise StopRun("universe", "Formal universe is empty")
    return result


def validate_codes(codes: tuple[str, ...], universe: list[str]) -> None:
    """Require a deterministic, unique scope contained in the formal universe."""

    if not codes or len(codes) > MAX_ASSETS:
        raise StopRun("asset_scope", "Asset scope is empty or exceeds 20 assets")
    if len(set(codes)) != len(codes) or codes != tuple(sorted(codes)):
        raise StopRun("asset_scope", "Asset scope is not unique and canonical")
    outside = sorted(set(codes).difference(universe))
    if outside:
        raise StopRun("universe_scope", f"Asset codes outside formal universe: {outside}")


def rows(codes: tuple[str, ...], lock: bool = False) -> list[dict[str, Any]]:
    """Read or NOWAIT-lock the complete null-availability set for assets."""

    query = FinancialFactModel._default_manager.filter(
        asset_code__in=codes, available_at__isnull=True
    ).order_by("id")
    if lock:
        query = query.select_for_update(nowait=True)
    return norm(list(query.values()))


def validate_source(rows_before: list[dict[str, Any]]) -> None:
    """Allow only akshare rows with a matching source_type and valid report date."""

    for row in rows_before:
        if row.get("source") != SOURCE:
            raise StopRun("unsupported_source", f"PK {row.get('id')} source is not akshare")
        extra = row.get("extra")
        if not isinstance(extra, dict) or extra.get("source_type") != SOURCE:
            raise StopRun("unsupported_source", f"PK {row.get('id')} source_type is not akshare")
        report_date = row.get("report_date")
        if not isinstance(report_date, str):
            raise StopRun("report_date", f"PK {row.get('id')} has no report_date")
        try:
            date.fromisoformat(report_date)
        except ValueError as exc:
            raise StopRun("report_date", f"PK {row.get('id')} report_date is invalid") from exc


def expected_after(before: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Build the exact image where only available_at derives from report_date."""

    result: list[dict[str, Any]] = []
    for row in before:
        report_date = row["report_date"]
        if not isinstance(report_date, str):
            raise StopRun("report_date", f"PK {row.get('id')} has no report_date")
        value = datetime.combine(date.fromisoformat(report_date), datetime.min.time(), tzinfo=UTC)
        copy = dict(row)
        copy["available_at"] = value.isoformat(sep=" ")
        result.append(copy)
    return result


def preview(codes: tuple[str, ...], recorded_at: datetime) -> dict[str, Any]:
    """Run the existing application preview for one asset-complete scope."""

    service = FinancialAvailabilityBackfillUseCase(
        repository=FinancialFactRepository(), transaction=transaction.atomic
    )
    return service.preview(asset_codes=codes, recorded_at=recorded_at).to_dict()


def validate_preview(value: dict[str, Any], row_count: int, asset_count: int) -> None:
    """Require exact full-set eligibility with no unresolved or future evidence."""

    if value.get("safe_to_execute") is not True:
        raise StopRun("preview", "Preview is not safe_to_execute")
    if value.get("missing_row_count") != row_count or value.get("eligible_row_count") != row_count:
        raise StopRun("preview", "Preview row count is not the complete null set")
    if value.get("eligible_asset_count") != asset_count:
        raise StopRun("preview", "Preview asset count is incomplete")
    for field in ("unresolved_row_count", "future_report_date_count", "future_available_at_count"):
        if value.get(field) != 0:
            raise StopRun("preview", f"Preview has nonzero {field}")


def groups(universe: list[str], recorded_at: datetime) -> list[dict[str, Any]]:
    """Aggregate pending rows deterministically by formal-universe asset."""

    query = (
        FinancialFactModel._default_manager.filter(
            asset_code__in=universe, available_at__isnull=True
        )
        .values("asset_code")
        .annotate(
            rows=Count("id"),
            unresolved=Count("id", filter=Q(report_date__isnull=True)),
            future=Count("id", filter=Q(report_date__gt=recorded_at.date())),
        )
        .order_by("asset_code")
    )
    return list(query)


def choose(
    grouped: list[dict[str, Any]],
    excluded: set[str],
    completed: set[str],
) -> tuple[tuple[str, ...], int] | None:
    """Choose consecutive complete assets without splitting or skipping blockers."""

    chosen: list[str] = []
    total = 0
    for item in grouped:
        code = item["asset_code"]
        count = int(item["rows"])
        if code in completed:
            if count:
                raise StopRun("reappeared_asset", f"Completed asset {code} has new null rows")
            continue
        if code in excluded:
            continue
        if not count:
            continue
        if item["unresolved"]:
            raise StopRun("unresolved_asset", f"Asset {code} has unresolved rows")
        if item["future"]:
            raise StopRun("future_asset", f"Asset {code} has future report dates")
        if count > MAX_ROWS:
            raise StopRun("oversize_asset", f"Asset {code} has {count} rows; cannot split PKs")
        if chosen and (len(chosen) == MAX_ASSETS or total + count > MAX_ROWS):
            break
        chosen.append(code)
        total += count
        if len(chosen) == MAX_ASSETS or total == MAX_ROWS:
            break
    if not chosen:
        return None
    return tuple(chosen), total


def preflight(
    index: int,
    excluded: set[str],
    completed: set[str],
    reserved: list[dict[str, Any]],
    run_hash: str | None,
) -> tuple[dict[str, Any] | None, list[str], str, list[str], int]:
    """Freeze one candidate in an independent read-only transaction."""

    with transaction.atomic():
        configure(True)
        candidate = candidate_identity()
        universe = load_universe()
        uhash = universe_hash(universe)
        if uhash != EXPECTED_UNIVERSE_HASH:
            raise StopRun("universe_drift", "Formal universe hash differs from approved hash")
        if run_hash is not None and uhash != run_hash:
            raise StopRun("universe_drift", "Universe hash changed during run")
        for old in reserved:
            if rows(tuple(old["asset_codes"])) != old["before"]:
                raise StopRun("dry_run_drift", "A reserved dry-run before image changed")
        recorded_at = timezone.now()
        grouped = groups(universe, recorded_at)
        pending_codes = [item["asset_code"] for item in grouped]
        pending_rows = sum(int(item["rows"]) for item in grouped)
        selected = choose(grouped, excluded, completed)
        if selected is None:
            return None, universe, uhash, pending_codes, pending_rows
        codes, expected_rows = selected
        validate_codes(codes, universe)
        before = rows(codes)
        if len(before) != expected_rows or {row["asset_code"] for row in before} != set(codes):
            raise StopRun("before_image", "Candidate is not a complete asset set")
        validate_source(before)
        before_ids = [row["id"] for row in before]
        if len(set(before_ids)) != len(before_ids):
            raise StopRun("before_image", "Before image contains duplicate PKs")
        p = preview(codes, recorded_at)
        validate_preview(p, len(before), len(codes))
        return (
            {
                "index": index,
                "recorded_at": recorded_at,
                "candidate": candidate,
                "universe": universe,
                "universe_hash": uhash,
                "asset_codes": codes,
                "before": before,
                "before_hash": digest(before),
                "before_ids": before_ids,
                "preview": p,
            },
            universe,
            uhash,
            pending_codes,
            pending_rows,
        )


def write_batch(plan: dict[str, Any]) -> dict[str, Any]:
    """Revalidate and execute one plan; never retry an uncertain commit."""

    body_done = False
    try:
        with transaction.atomic():
            configure(False)
            candidate = candidate_identity()
            universe = load_universe()
            validate_codes(tuple(plan["asset_codes"]), universe)
            if universe_hash(universe) != plan["universe_hash"]:
                raise StopRun("universe_drift", "Universe hash changed before write")
            if candidate != plan["candidate"]:
                raise StopRun("candidate_drift", "Release identity changed before write")
            before = rows(tuple(plan["asset_codes"]), lock=True)
            if before != plan["before"] or digest(before) != plan["before_hash"]:
                raise StopRun("before_drift", "Locked before image differs from preflight")
            validate_source(before)
            p = preview(tuple(plan["asset_codes"]), plan["recorded_at"])
            if norm(p) != norm(plan["preview"]):
                raise StopRun("preview_drift", "Write preview differs from preflight")
            validate_preview(p, len(before), len(plan["asset_codes"]))
            service = FinancialAvailabilityBackfillUseCase(
                repository=FinancialFactRepository(), transaction=transaction.atomic
            )
            outcome = service.execute(
                asset_codes=tuple(plan["asset_codes"]), recorded_at=plan["recorded_at"]
            )
            after = norm(
                list(
                    FinancialFactModel._default_manager.filter(pk__in=plan["before_ids"])
                    .order_by("id")
                    .values()
                )
            )
            if outcome.updated_row_count != len(before) or outcome.after.eligible_row_count != 0:
                raise StopRun("write_count", "UseCase count contract failed")
            if after != expected_after(before):
                raise StopRun("field_drift", "Only available_at may change")
            repeated = service.execute(
                asset_codes=tuple(plan["asset_codes"]), recorded_at=plan["recorded_at"]
            )
            if repeated.updated_row_count != 0:
                raise StopRun("idempotency", "Same-transaction rerun updated rows")
            body_done = True
            return {
                "outcome": outcome.to_dict(),
                "after": after,
                "after_hash": digest(after),
                "idempotent_repeat": repeated.to_dict(),
            }
    except StopRun:
        raise
    except Exception as exc:
        if body_done:
            raise UncertainCommit(str(exc)) from exc
        raise


def postflight(plan: dict[str, Any], expected: list[dict[str, Any]], execute: bool) -> dict[str, Any]:
    """Verify the committed or dry-run image in an independent read-only transaction."""

    with transaction.atomic():
        configure(True)
        candidate = candidate_identity()
        universe = load_universe()
        if universe_hash(universe) != EXPECTED_UNIVERSE_HASH or universe_hash(universe) != plan["universe_hash"]:
            raise StopRun("universe_drift", "Universe hash changed at postflight")
        if candidate != plan["candidate"]:
            raise StopRun("candidate_drift", "Release identity changed at postflight")
        after = norm(
            list(
                FinancialFactModel._default_manager.filter(pk__in=plan["before_ids"])
                .order_by("id")
                .values()
            )
        )
        if after != expected:
            raise StopRun("postflight_fields", "Postflight image differs from expected")
        pending = rows(tuple(plan["asset_codes"]))
        if (execute and pending) or (not execute and pending != plan["before"]):
            raise StopRun("postflight_pending", "Postflight null set differs from expectation")
        return {"after": after, "after_hash": digest(after), "pending_rows": len(pending)}


def remaining(expected_hash: str | None) -> dict[str, Any]:
    """Read the current formal-universe remainder after the batch limit."""

    with transaction.atomic():
        configure(True)
        candidate_identity()
        universe = load_universe()
        current_hash = universe_hash(universe)
        if current_hash != EXPECTED_UNIVERSE_HASH or (expected_hash is not None and current_hash != expected_hash):
            raise StopRun("universe_drift", "Universe hash changed while reading remaining scope")
        grouped = groups(universe, timezone.now())
        return {
            "asset_codes": [item["asset_code"] for item in grouped],
            "rows": sum(int(item["rows"]) for item in grouped),
            "universe_hash": current_hash,
        }


def emit(record: dict[str, Any]) -> None:
    """Emit one JSONL evidence record."""

    print(json.dumps(record, default=str, sort_keys=True), flush=True)


def main(argv: list[str] | None = None) -> int:
    """Run at most ten batches and stop immediately on any guard failure."""

    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--execute", action="store_true")
    parser.add_argument("--max-batches", type=int, choices=range(1, MAX_BATCHES + 1), default=MAX_BATCHES)
    parser.add_argument("--operator", default="codex-delegated-data02-executor")
    args = parser.parse_args(sys.argv[1:] if argv is None else argv)
    if not args.operator or "\n" in args.operator or "\r" in args.operator:
        parser.error("--operator must be a non-empty single-line label")
    mode = "execute" if args.execute else "dry_run"
    excluded: set[str] = set()
    completed: set[str] = set()
    reserved: list[dict[str, Any]] = []
    run_hash: str | None = None
    started = timezone.now().isoformat()
    for index in range(1, args.max_batches + 1):
        active_base: dict[str, Any] | None = None
        try:
            plan, universe, uhash, pending_codes, pending_rows = preflight(
                index, excluded, completed, reserved, run_hash
            )
            run_hash = run_hash or uhash
            if plan is None:
                status = "complete" if not pending_codes else "dry_run_scope_planned"
                emit({"status": status, "mode": mode, "universe": universe, "universe_hash": uhash,
                      "remaining": {"asset_codes": pending_codes, "rows": pending_rows},
                      "finished_at": timezone.now().isoformat()})
                return 0
            base = {"status": "planned", "mode": mode, "batch_index": index, "operator": args.operator,
                    "operator_is_human_signer": False, "source": SOURCE,
                    "backup_sha256_declarations": {"local": LOCAL_BACKUP_SHA256, "remote_latest": REMOTE_BACKUP_SHA256},
                    "candidate": plan["candidate"], "universe": universe, "universe_hash": uhash,
                    "asset_codes": plan["asset_codes"],
                    "recorded_at": plan["recorded_at"].isoformat(), "before": plan["before"],
                    "before_hash": plan["before_hash"], "before_ids": plan["before_ids"], "preview": plan["preview"]}
            active_base = base
            if not args.execute:
                pf = postflight(plan, plan["before"], False)
                base.update({"status": "dry_run", "after": pf["after"], "after_hash": pf["after_hash"],
                             "result": {"would_update": len(plan["before"])}, "postflight": pf})
                emit(base)
                reserved.append(plan)
            else:
                emit({**base, "status": "planned", "commit_state": "not_started"})
                result = write_batch(plan)
                committed = {**base, "status": "committed", "commit_state": "committed",
                             "after": result["after"], "after_hash": result["after_hash"],
                             "result": result}
                emit(committed)
                try:
                    pf = postflight(plan, result["after"], True)
                except StopRun as exc:
                    emit({**committed, "status": "postflight_failed", "error": {"code": exc.code, "message": exc.message}})
                    return 1
                except Exception as exc:
                    emit({**committed, "status": "postflight_failed", "error": {"type": type(exc).__name__, "message": str(exc)}})
                    return 1
                emit({**committed, "status": "success", "postflight": pf})
                completed.update(plan["asset_codes"])
            excluded.update(plan["asset_codes"])
        except UncertainCommit as exc:
            record = dict(active_base or {"mode": mode, "batch_index": index})
            record.update({"status": "uncertain_commit", "commit_state": "unknown",
                           "error": {"code": exc.code, "message": exc.message}})
            emit(record)
            return 1
        except StopRun as exc:
            record = dict(active_base or {"mode": mode, "batch_index": index})
            record.update({"status": "blocked", "commit_state": "rolled_back" if args.execute else "not_committed",
                           "error": {"code": exc.code, "message": exc.message}})
            emit(record)
            return 1
        except Exception as exc:
            record = dict(active_base or {"mode": mode, "batch_index": index})
            record.update({"status": "error", "commit_state": "unknown" if args.execute else "not_committed",
                           "error": {"type": type(exc).__name__, "message": str(exc)}})
            emit(record)
            return 1
    try:
        scope_remaining = remaining(run_hash)
    except StopRun as exc:
        emit({"status": "blocked", "mode": mode,
              "error": {"code": exc.code, "message": exc.message}})
        return 1
    emit({"status": "max_batches_reached", "mode": mode, "max_batches": args.max_batches,
          "universe_hash": run_hash, "remaining": scope_remaining,
          "planned_not_written": [p["asset_codes"] for p in reserved],
          "started_at": started, "finished_at": timezone.now().isoformat()})
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
